from typing import Any
from pydantic import ConfigDict, Field, model_validator
from nanobrain.core.step import BaseStep, StepConfig

class ThresholdStepConfig(StepConfig):
    model_config = ConfigDict(extra="forbid", validate_assignment=False)
    threshold: float = Field(default=0.0)

    @model_validator(mode="before")
    @classmethod
    def _strip_framework_keys(cls, data: Any) -> Any:
        if isinstance(data, dict):
            data.pop("class", None)
        return data

class ThresholdStep(BaseStep):
    COMPONENT_TYPE = "threshold_step"

    @classmethod
    def _get_config_class(cls):
        return ThresholdStepConfig

    def __init__(self, config: ThresholdStepConfig):
        self._threshold = config.threshold

    async def process(self, input_data: dict, **kwargs) -> dict:
        items = input_data.get("items", [])
        return {"above": [x for x in items if x > self._threshold]}

from nanobrain.core.step import BaseStep

class DedupePreserveOrderStep(BaseStep):
    COMPONENT_TYPE = "dedupe_preserve_order"

    async def process(self, input_data: dict, **kwargs) -> dict:
        seen = set()
        unique_items = []
        for item in input_data["items"]:
            if item not in seen:
                seen.add(item)
                unique_items.append(item)
        return {"unique": unique_items}

