from nanobrain.core.tool import ToolBase
import ast

class CalculatorTool(ToolBase):
    async def execute(self, expression: str) -> dict:
        try:
            tree = ast.parse(expression, mode='eval')
            if not all(isinstance(node, (ast.Num, ast.BinOp, ast.UnaryOp)) for node in ast.walk(tree)):
                raise ValueError("Invalid arithmetic expression")
            result = eval(compile(tree), {})
            return {"result": result}
        except Exception as e:
            raise ValueError(f"Invalid arithmetic expression: {e}")
